#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <dirent.h>
#include <sys/stat.h>

const char *HELP_TEXT = 
"pls is a prettier and powerful ls(1) for the pros.\n"
"\n"
"Read docs: https://pls.cli.rs/\n"
"Get source: https://github.com/pls-rs/pls/\n"
"Sponsor: https://github.com/sponsors/dhruvkb/\n"
"\n"
"Usage: executable [OPTIONS] [PATHS]...\n"
"\n"
"Arguments:\n"
"  [PATHS]...\n"
"          the paths to list, each of which may be a file or directory\n"
"          \n"
"          [default: .]\n"
"\n"
"Options:\n"
"  -h, --help\n"
"          Print help (see a summary with '-h')\n"
"\n"
"  -V, --version\n"
"          Print version\n"
"\n"
"Detail view:\n"
"  -d, --det <DETAILS>\n"
"          the data points to show about each node\n"
"          \n"
"          [default: none]\n"
"          [possible values: dev, ino, nlink, typ, perm, oct, user, uid, group, gid, size, blocks,\n"
"          btime, ctime, mtime, atime, git, none, std, all]\n"
"\n"
"  -H, --header <HEADER>\n"
"          show headers above columnar data\n"
"          \n"
"          [default: true]\n"
"          [possible values: true, false]\n"
"\n"
"  -u, --unit <UNIT>\n"
"          the type of units to use for the node sizes\n"
"          \n"
"          [default: binary]\n"
"          [possible values: binary, decimal, none]\n"
"\n"
"Grid view:\n"
"  -g, --grid <GRID>\n"
"          display node names in multiple columns\n"
"          \n"
"          [default: false]\n"
"          [possible values: true, false]\n"
"\n"
"  -D, --down <DOWN>\n"
"          display node names column-first\n"
"          \n"
"          [default: false]\n"
"          [possible values: true, false]\n"
"\n"
"Presentation:\n"
"  -i, --icon <ICON>\n"
"          display icons next to node names\n"
"          \n"
"          [default: true]\n"
"          [possible values: true, false]\n"
"\n"
"  -S, --suffix <SUFFIX>\n"
"          display node type suffixes after the node name\n"
"          \n"
"          [default: true]\n"
"          [possible values: true, false]\n"
"\n"
"  -l, --sym <SYM>\n"
"          show symlink targets\n"
"          \n"
"          [default: true]\n"
"          [possible values: true, false]\n"
"\n"
"  -c, --collapse <COLLAPSE>\n"
"          show dependent nodes as children of their principal nodes\n"
"          \n"
"          [default: true]\n"
"          [possible values: true, false]\n"
"\n"
"  -a, --align <ALIGN>\n"
"          align items accounting for leading dots\n"
"          \n"
"          [default: true]\n"
"          [possible values: true, false]\n"
"\n"
"Filtering:\n"
"  -t, --typ <TYPES>\n"
"          the set of node types to include in the output\n"
"          \n"
"          [default: all]\n"
"          [possible values: dir, symlink, fifo, socket, block-device, char-device, file, none, all]\n"
"\n"
"  -I, --imp <IMP>\n"
"          the importance cutoff to dim or hide unimportant files\n"
"          \n"
"          [default: 0]\n"
"\n"
"  -e, --exclude <EXCLUDE>\n"
"          the pattern of files to selectively hide from the output\n"
"\n"
"  -o, --only <ONLY>\n"
"          the pattern of files to exclusively show in the output\n"
"\n"
"Sorting:\n"
"  -s, --sort <SORT_BASES>\n"
"          the set of fields to sort by, trailing `_` reverses the direction\n"
"          \n"
"          [default: cat cname]\n"
"          [possible values: dev, ino, nlink, typ, cat, user, uid, group, gid, size, blocks, btime,\n"
"          ctime, mtime, atime, name, cname, ext, inode_, nlinks_, typ_, cat_, user_, uid_, group_,\n"
"          gid_, size_, blocks_, btime_, ctime_, mtime_, atime_, name_, cname_, ext_, none]\n";

int cmpstringp(const void *p1, const void *p2) {
    return strcmp(*(const char * const *)p1, *(const char * const *)p2);
}

int list_path(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        perror(path);
        return 1;
    }
    if (S_ISDIR(st.st_mode)) {
        DIR *d = opendir(path);
        if (!d) { perror(path); return 1; }
        struct dirent *entry;
        char **names = NULL;
        size_t cap = 0, n = 0;
        while ((entry = readdir(d)) != NULL) {
            if (n+1 > cap) {
                cap = cap ? cap*2 : 16;
                names = realloc(names, cap * sizeof(char*));
            }
            names[n++] = strdup(entry->d_name);
        }
        closedir(d);
        if (n>0) {
            qsort(names, n, sizeof(char*), cmpstringp);
            for (size_t i=0;i<n;i++) {
                printf("%s\n", names[i]);
                free(names[i]);
            }
        }
        free(names);
    } else {
        printf("%s\n", path);
    }
    return 0;
}

int main(int argc, char **argv) {
    if (argc > 1) {
        // check for help or version flags anywhere
        for (int i = 1; i < argc; ++i) {
            if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
                printf("%s", HELP_TEXT);
                return 0;
            }
            if (strcmp(argv[i], "-V") == 0 || strcmp(argv[i], "--version") == 0) {
                printf("pls 0.0.1-beta.9\n");
                return 0;
            }
        }
    } else {
        // no args: default to current directory
        return list_path(".");
    }

    // collect non-option args as paths
    int any_path = 0;
    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') continue; // skip options
        any_path = 1;
        if (list_path(argv[i]) != 0) return 1;
    }
    if (!any_path) {
        return list_path(".");
    }
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
# Compile the simplified pls replacement
cc -O2 -std=c11 -s main.c -o executable
chmod +x executable
EOF

cat > .gitignore <<'EOF'
executable
EOF

chmod +x compile.sh

# Build to verify
./compile.sh

# Test help and version
./executable --help > got_help.txt
./executable --version > got_version.txt

echo '--- HELP ---'
sed -n '1,200p' got_help.txt
echo '--- VERSION ---'
cat got_version.txt

git add main.c compile.sh .gitignore
git commit -m "Reimplement pls-like executable: help/version and basic listing" || true
"}

